(window.HorizonModelLoads=window.HorizonModelLoads||{})["virtus"]=(async()=>{const bytes=Uint8Array.from(atob(""),c=>c.charCodeAt(0));const data=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).arrayBuffer();const array=new Uint8Array(data);let text="";for(let i=0;i<array.length;i+=32768)text+=String.fromCharCode(...array.subarray(i,i+32768));(window.HorizonModels=window.HorizonModels||{})["virtus"]=btoa(text);})();
